// pure handler in ask.ts. The Gemini key is a Wrangler secret and never ships
// in the app.

// Generated by `npm run grounding` (gitignored: rulebook text isn't ours to republish).
// eslint-disable-next-line import/no-unresolved
import grounding from './grounding.generated.txt';

import { handleAsk, type AskEnv, type RateLimiter } from './ask.ts';

interface Env extends AskEnv {
  ASK_LIMITER: RateLimiter;
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const { status, body } = await handleAsk(
      {
        method: request.method,
        path: new URL(request.url).pathname,
        header: (name) => request.headers.get(name),
        ip: request.headers.get('cf-connecting-ip') ?? 'unknown',
        bodyText: () => request.text(),
      },
      env,
      { fetch: (input, init) => fetch(input, init), limiter: env.ASK_LIMITER, grounding },
    );
    return Response.json(body, { status });
  },
};
